const item = $input.first();
const description = String(item.json?.task_description || '').trim();
const taskId = `mvp_${Date.now()}_${Math.random().toString(36).slice(2, 10)}`;
const binary = item.binary && typeof item.binary === 'object' ? item.binary : {};
const inputFiles = Object.entries(binary).map(([field, file]) => ({
  field,
  filename: String(file?.fileName || ''),
  mime_type: String(file?.mimeType || ''),
}));
// Keep Orchestrator binary keys: file / schedule_file(s)* / trajectory_files* / surface_file.
const mappedBinary = {};
for (const [field, file] of Object.entries(binary)) {
  if (!file) continue;
  if (field === 'file' || field === 'surface_file' || field === 'trajectory_files' || /^(schedule_file|schedule_files)\d*$/i.test(field) || /^trajectory_files\d*$/i.test(field)) {
    mappedBinary[field] = file;
  }
}
const scheduleRoot = String(item.json?.schedule_root || '').trim();
const request = {
  objective: description,
  problem_statement: description,
  task_description: description,
  input_files: inputFiles,
};
if (scheduleRoot) request.schedule_root = scheduleRoot;
const hasSchedule = Object.keys(mappedBinary).some((k) => /^(schedule_file|schedule_files)\d*$/i.test(k));
if (hasSchedule) request.build_mode = 'AUTO';
return [{
  json: {
    entrypoint: 'mvp_form',
    action: 'start',
    task_id: taskId,
    task_description: description,
    request_text: description,
    request,
    schedule_root: scheduleRoot || undefined,
    context: {
      source: 'mvp-entry-form',
      submitted_task_id: taskId,
    },
    requested_by: 'mvp-form-engineer',
  },
  binary: mappedBinary,
}];

const response = $input.first().json || {};
const escapeHtml = (value) => String(value ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/\"/g, '&quot;')
  .replace(/'/g, '&#39;');
const prettyJson = (value, limit = 16000) => {
  let text;
  try { text = JSON.stringify(value, null, 2); } catch { text = String(value); }
  return text.length > limit ? `${text.slice(0, limit)}\n… truncated for display` : text;
};
const questionText = (q) => {
  if (!q || typeof q !== 'object') return String(q ?? '');
  return String(q.text || q.question || q.message || q.id || '').trim();
};
const result = response.result && typeof response.result === 'object' ? response.result : null;
const deliverables = Array.isArray(result?.deliverables) ? result.deliverables : [];
const scheduleText = response.schedule_text
  || result?.release?.schedule_text
  || result?.compact_data?.generated_schedule
  || deliverables.find((value) => typeof value?.schedule_text === 'string')?.schedule_text
  || null;
const gate = response.human_gate && typeof response.human_gate === 'object' ? response.human_gate : null;
const questions = Array.isArray(gate?.questions) ? gate.questions : [];
const status = String(response.status || 'error');
const taskId = String(response.task_id || '');
const version = response.version ?? null;
const message = String(response.message || (scheduleText ? 'SCHEDULE generated.' : 'MAS task completed.'));
const questionItems = questions
  .map((q, index) => `<li><strong>${escapeHtml(String(q.id || `q${index + 1}`))}</strong>: ${escapeHtml(questionText(q))}${q.expected_format ? ` <em>(format: ${escapeHtml(q.expected_format)})</em>` : ''}${q.required === false ? '' : ' <strong>*</strong>'}</li>`)
  .join('');
const gateBlock = gate
  ? `<section>
<h2>Human input required</h2>
<p><strong>What is wrong / why stopped:</strong> ${escapeHtml(gate.reason || message)}</p>
<p><strong>Gate kind:</strong> <code>${escapeHtml(gate.kind || 'needs_input')}</code></p>
${questionItems ? `<p><strong>What the orchestrator needs from you:</strong></p><ol>${questionItems}</ol>` : '<p>No structured questions were returned; use the reason above.</p>'}
<p><strong>What you should do next:</strong></p>
<ol>
<li>Copy Task ID <code>${escapeHtml(taskId)}</code></li>
<li>Open the published form <strong>Form — MAS Human Gate</strong> (<code>/form/mas-human-gate</code>)</li>
<li>Paste the Task ID, choose action (<code>reply</code> / <code>approve</code> / <code>reject</code>), and answer in plain language</li>
<li>Do <em>not</em> copy version/gate_id manually — Human Gate loads them from task status</li>
</ol>
</section>`
  : '';
const scheduleBlock = scheduleText
  ? `<section><h2>schedule.inc</h2><pre>${escapeHtml(String(scheduleText).slice(0, 100000))}</pre></section>`
  : '';
const html = `<main>
<h1>MAS task result</h1>
<p>Status: <strong>${escapeHtml(status)}</strong></p>
<p>${escapeHtml(message)}</p>
<p>Task ID: <code>${escapeHtml(taskId || 'n/a')}</code></p>
<p>Version: <code>${escapeHtml(version ?? 'n/a')}</code></p>
${gateBlock}
${scheduleBlock}
<details><summary>Structured orchestrator response</summary><pre>${escapeHtml(prettyJson(response))}</pre></details>
</main>`;
return [{ json: {
  task_id: taskId || null,
  status,
  message,
  version,
  schedule_text: scheduleText,
  human_gate: gate,
  result: result || response,
  form_response_html: html,
}}];
